/**
 * True when `member` is a current membership: active and not removed. A
 * removed member keeps its row (and its `status`) for the audit log, so
 * `archivedAt` must be checked alongside `status` — this is the one place
 * that states the rule.
 */
export function isCurrentMember(
  member: Member | null | undefined,
): member is Member {
  return (
