export async function acceptInvitation(
  userId: UserId,
  input: AcceptInvitationTokenInput,
): Promise<Member> {
  const invitation = requireFound(
    await invitationRepo.findInvitationByTokenHash(hashToken(input.token)),
    "Invitation",
    "token",
  );

  if (invitation.revokedAt !== null) {
    throw new Error("That invitation has been revoked");
  }
  if (invitation.acceptedAt !== null) {
    throw new Error("That invitation has already been accepted");
  }
  if (invitation.expiresAt <= toIsoTimestamp(new Date())) {
    throw new Error("That invitation has expired");
  }

  const acceptedAt = toIsoTimestamp(new Date());
  const existing = await memberRepo.findMember(invitation.orgId, userId);

  // An invitation is used up by being accepted, whoever accepts it. A current
  // member (or a suspended one) is left exactly as they were.
  if (existing && existing.archivedAt === null && existing.status !== "invited") {
    await invitationRepo.markInvitationAccepted(
      invitation.orgId,
      invitation.id,
      acceptedAt,
    );
    return existing;
  }

  // A former member is re-admitted on the membership the org already knows,
  // rather than given a second row the unique (org, user) index would refuse.
  const member = existing
    ? await memberRepo.reactivateMember(
        invitation.orgId,
        existing.id,
        invitation.role,
        invitation.invitedBy,
        acceptedAt,
      )
    : await memberRepo.insertMember(
        invitation.orgId,
        userId,
        invitation.role,
        invitation.invitedBy,
      );

  await invitationRepo.markInvitationAccepted(
    invitation.orgId,
