import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { hashToken } from "@/lib/hash";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as memberService from "@/server/services/member-service";
import * as invitationService from "@/server/services/invitation-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as commentService from "@/server/services/comment-service";
import * as sessionService from "@/server/services/session-service";
import { registerEventHandlers } from "@/server/services/event-registry";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); registerEventHandlers(); });
afterAll(() => cleanup());

describe("removal", () => {
  it("full scenario", async () => {
    const t = await createTenant("rm-scn", "growth");
    await usageRepo.recomputeUsage(t.org.id);
    const m = (await memberRepo.findMember(t.org.id, t.userIds.member))!;
    const issue = await issueService.createIssue(t.actors.owner, issueInput(t.org.id, t.project.id, { assigneeId: t.userIds.member }));
    const proj = await projectService.createProject(t.actors.owner, { orgId: t.org.id, name: "Other", slug: "other", key: "OTH", description: null, visibility: "org", leadId: t.userIds.member, color: "#6366f1", targetDate: null });
    const before = (await usageRepo.recomputeUsage(t.org.id)).seatsUsed;

    await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: m.id });
    expect((await issueRepo.findIssueById(t.org.id, issue.id))!.assigneeId).toBeNull();
    expect((await projectRepo.findProjectById(t.org.id, proj.id))!.leadId).toBeNull();

    await expect(memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: m.id })).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(memberService.updateMemberRole(t.actors.owner, { orgId: t.org.id, memberId: m.id, role: "admin" })).rejects.toBeInstanceOf(AlreadyArchivedError);

    await expect(commentService.createComment(t.actors.member, { orgId: t.org.id, issueId: issue.id, body: "hi", parentId: null, mentionedUserIds: [] } as never)).rejects.toThrow();
    const principal = { userId: t.userIds.member, email: "x", activeOrgId: t.org.id, expiresAt: "2099-01-01T00:00:00.000Z" } as never;
    expect(await sessionService.resolveActorForOrg(principal, t.org.slug)).toBeNull();
    await expect(sessionService.switchActiveOrg(principal, { orgId: t.org.id } as never)).rejects.toThrow();

    await expect(issueService.assignIssue(t.actors.owner, { orgId: t.org.id, issueId: issue.id, assigneeId: t.userIds.member })).rejects.toThrow(/not a member/);
    const count = await issueRepo.countIssues(t.org.id, t.project.id);
    await expect(issueService.createIssue(t.actors.owner, issueInput(t.org.id, t.project.id, { assigneeId: t.userIds.member }))).rejects.toThrow();
    expect(await issueRepo.countIssues(t.org.id, t.project.id)).toBe(count);

    // notifications: comment on an issue authored by removed member
    const own = await issueService.createIssue(t.actors.admin, issueInput(t.org.id, t.project.id));
    await commentService.createComment(t.actors.owner, { orgId: t.org.id, issueId: issue.id, body: "@x", parentId: null, mentionedUserIds: [t.userIds.member] } as never);
    const notes = await notificationRepo.listNotifications({ orgId: t.org.id, recipientId: t.userIds.member, limit: 50, cursor: null } as never);
    expect(notes.items.length).toBe(0);

    // re-invite
    const token = "z".repeat(32);
    await invitationRepo.insertInvitation(t.org.id, { orgId: t.org.id, email: "member@rm-scn.test", role: "viewer", expiresInDays: 14 }, t.userIds.admin, hashToken(token));
    const back = await invitationService.acceptInvitation(t.userIds.member, { token });
    expect(back.id).toBe(m.id);
    expect(back.archivedAt).toBeNull();
    expect(back.role).toBe("viewer");
    expect(back.invitedBy).toBe(t.userIds.admin);
    const list = await memberRepo.listMembers({ orgId: t.org.id, limit: 50, cursor: null } as never);
    expect(list.items.filter((x) => x.userId === t.userIds.member).length).toBe(1);
    expect((await orgRepo.listOrgsForUser(t.userIds.member)).length).toBe(1);
    expect((await usageRepo.getUsage?.(t.org.id))?.seatsUsed ?? before).toBe(before);

    // current member accepts
    const token2 = "y".repeat(32);
    const inv2 = await invitationRepo.insertInvitation(t.org.id, { orgId: t.org.id, email: "admin@rm-scn.test", role: "viewer", expiresInDays: 14 }, t.userIds.owner, hashToken(token2));
    const a = await invitationService.acceptInvitation(t.userIds.admin, { token: token2 });
    expect(a.role).toBe("admin");
    await expect(invitationService.acceptInvitation(t.userIds.admin, { token: token2 })).rejects.toThrow(/already/);
    void inv2; void own;
  });
});
EOF
